"""SOLVE-IT Digital Forensics Knowledge Base and Ontology — solveit-analysis module."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional


@dataclass
class ForensicToolTagBasedReport:
    """A report generated by a forensic tool based on tags added during analysis."""

    CLASS_IRI: str = "https://ontology.solveit-df.org/solveit/analysis/ForensicToolTagBasedReport"
    created_by: Optional[IdentityAbstraction] = field(default=None)
    description: list[str] = field(default_factory=list)
    external_reference: list[ExternalReference] = field(default_factory=list)
    has_facet: list[Facet] = field(default_factory=list)
    modified_time: list[datetime] = field(default_factory=list)
    name: Optional[str] = field(default=None)
    object_created_time: Optional[datetime] = field(default=None)
    object_marking: list[MarkingDefinitionAbstraction] = field(default_factory=list)
    object_status: Optional[str] = field(default=None)
    spec_version: Optional[str] = field(default=None)
    tag: list[str] = field(default_factory=list)
    statement: list[str] = field(default_factory=list)


